import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Modal, ModalProps, Tag, Typography } from 'antd';
import cn from 'classnames';

import SendIcon from 'assets/images/icons/send.svg?react';
import { EPaymentModel, EPaymentModelMap } from 'entities/Brand';
import { useBrand } from 'entities/Brand/hooks/useBrand';
import { useBrandSlice } from 'entities/Brand/hooks/useBrandSlice';

import styles from './DetailsPopup.module.scss';

interface IDetailsPopupProps extends ModalProps {}

export const DetailsPopup: FC<IDetailsPopupProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { setIsOpenSaveToCollectionsDrawer, isOpenDetailsPopup, setIsOpenDetailsPopup } = useBrandSlice();
	const { handleSendClick } = useBrand();
	const { post } = useBrandSlice();

	const handleSaveClick = () => {
		setIsOpenSaveToCollectionsDrawer(true);
	};

	const items = [
		{
			term: t('Модель'),
			description: (post?.payment_model as EPaymentModel[])?.map((paymentModel: EPaymentModel) => (
				<Tag key={paymentModel} color={EPaymentModelMap[paymentModel].color}>
					{EPaymentModelMap[paymentModel].text}
				</Tag>
			)),
		},
		{ term: t('Выплата'), description: '-' },
		{ term: t('GEO'), description: post?.geo?.join(', ') },
		{ term: t('Подтверждение'), description: '-' },
		{ term: t('CR'), description: '' },
		{ term: t('EPC'), description: '' },
		{ term: t('Срок действия'), description: '' },
		{ term: t('Особенности'), description: '' },
		{ term: t('Условия'), description: '' },
		{
			term: t('Партнерская ссылка'),
			description: (
				<Typography.Text copyable ellipsis>
					{post?.link}
				</Typography.Text>
			),
		},
	];

	return (
		<Modal
			className={cn(className, styles.detailsPopup)}
			destroyOnHidden
			footer={null}
			open={isOpenDetailsPopup}
			onCancel={() => setIsOpenDetailsPopup(false)}
			{...props}>
			<dl className={styles.detailsPopup__dl}>
				{items.map((item) => (
					<div key={item.term} className={styles.detailsPopup__line}>
						<dt>
							<Typography.Text type={'secondary'}>{item.term}:</Typography.Text>
						</dt>
						<dd className={styles.detailsPopup__dd}>{item.description}</dd>
					</div>
				))}
			</dl>
			<Flex gap={4}>
				<Button style={{ flexShrink: 0 }} icon={<SendIcon />} onClick={handleSendClick} />
				<Button type="primary" onClick={handleSaveClick} block>
					{t('Сохранить в коллекцию')}
				</Button>
			</Flex>
		</Modal>
	);
};
