import { FC } from 'react';

import { Drawer, DrawerProps } from 'antd';
import cn from 'classnames';

import { useBrand } from 'entities/Brand/hooks/useBrand';
import { useBrandSlice } from 'entities/Brand/hooks/useBrandSlice';

import { CreateCollectionForm } from '../CreateCollectionForm/CreateCollectionForm';

import styles from './CreateCollectionDrawer.module.scss';

interface ICollectionDrawerProps extends DrawerProps {}

export const CreateCollectionDrawer: FC<ICollectionDrawerProps> = ({ className, ...props }) => {
	const { setIsOpenCreateCollectionDrawer, isOpenCreateCollectionDrawer } = useBrandSlice();
	const { t, contextHolder } = useBrand();

	// const handleCancelClick = () => {
	//
	// }

	return (
		<>
			{contextHolder}
			<Drawer
				title={t('Создать коллекцию и сохранить в неё пост')}
				onClose={() => setIsOpenCreateCollectionDrawer(false)}
				open={isOpenCreateCollectionDrawer}
				placement="bottom"
				className={cn(className, styles.createCollectionDrawer)}
				destroyOnHidden
				{...props}>
				<CreateCollectionForm handleCancelClick={() => setIsOpenCreateCollectionDrawer(false)} />
			</Drawer>
		</>
	);
};
