import { FC, HTMLAttributes } from 'react';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import { BrandInfo, CatalogPostCard, DetailsPopup, SaveToCollectionDrawer } from 'entities/Brand';
import { CreateCollectionDrawer } from 'entities/Collection';
import { MOCK_BRAND } from 'shared/consts/MOCK_FOR_CATALOG';
import { Page } from 'shared/ui';

import styles from './Brand.module.scss';

interface IBrandProps extends HTMLAttributes<HTMLDivElement> {}

export const Brand: FC<IBrandProps> = ({ className, ...props }) => {
	const { id } = useParams();
	const brand = MOCK_BRAND.find((brand) => brand.id === id) || MOCK_BRAND[0];

	return (
		<Page {...props} className={cn(className, styles.brand)}>
			<BrandInfo brand={brand} />
			<div className={styles.brand__postList}>
				{brand.posts?.map((offer) => <CatalogPostCard key={offer.id} post={offer} />)}
			</div>
			<DetailsPopup />
			<CreateCollectionDrawer />
			<SaveToCollectionDrawer />
		</Page>
	);
};

export default Brand;
