import { FC, HTMLAttributes } from 'react';

import { Button, Drawer, Flex, Typography } from 'antd';
import cn from 'classnames';

import PlusIcon from 'assets/images/icons/plus-rect.svg?react';
import noNameImg from 'assets/images/no_name.webp';
import { useBrand } from 'entities/Brand/hooks/useBrand';
import { useBrandSlice } from 'entities/Brand/hooks/useBrandSlice';
import { MOCK_COLLECTIONS } from 'shared/consts/MOCK_FOR_CATALOG';

import styles from './SaveToCollectionDrawer.module.scss';

interface ISaveToCollectionDrawerProps extends HTMLAttributes<HTMLDivElement> {}

export const SaveToCollectionDrawer: FC<ISaveToCollectionDrawerProps> = ({ className, ...props }) => {
	const { isOpenSaveToCollectionsDrawer, setIsOpenSaveToCollectionsDrawer, setIsOpenCreateCollectionDrawer } =
		useBrandSlice();
	const { t, contextHolder, saveToCollection } = useBrand();

	const collections = MOCK_COLLECTIONS; //TODO

	const handleNewCollectionClick = () => {
		setIsOpenCreateCollectionDrawer(true);
	};

	return (
		<>
			{contextHolder}
			<Drawer
				title={t('Сохранить пост в коллекцию')}
				onClose={() => setIsOpenSaveToCollectionsDrawer(false)}
				open={isOpenSaveToCollectionsDrawer}
				placement="bottom"
				className={cn(className, styles.saveToCollectionDrawer)}
				destroyOnHidden
				{...props}>
				<Flex gap={8} vertical>
					<Flex gap={4} className={styles.saveToCollectionDrawer__list}>
						{collections.map((collection) => (
							<Button
								className={styles.saveToCollectionDrawer__btn}
								key={collection.id}
								onClick={() => saveToCollection(collection.id)}>
								{collection.name}
								<Typography.Text type="secondary">
									{t('Постов')}: {collection.items.length}
								</Typography.Text>
								<img className={styles.saveToCollectionDrawer__icon} src={noNameImg} alt={''} width={28} height={28} />
								{/*<span className={styles.saveToCollectionDrawer__icon}>{collection.icon}</span>*/}
							</Button>
						))}
						<Button className={styles.saveToCollectionDrawer__btn} onClick={handleNewCollectionClick}>
							{t('Новая коллекция')}
							<PlusIcon className={styles.saveToCollectionDrawer__icon} />
						</Button>
					</Flex>
					<Button onClick={() => saveToCollection()} size={'large'} block>
						{t('Сохранить без коллекции')}
					</Button>
				</Flex>
			</Drawer>
		</>
	);
};
